PACKET_TEXT='{"kind":"public-source-only-no-runtime-data","stage":"s2","source":"0edb4ceeff2f7afbe42a62d8eef983a33fd1f44f","files":[{"name":"801_http.py","bytes":16852,"sha256":"ef065f56e74e8bb1b6c8289bfe5618cbfe3b130e95dcdfea54e4483b109971d3","gzip_base64":""},{"name":"801_stage2.py","bytes":10581,"sha256":"ab8f45594df9ab234ea6ce6c87930a799e4c9057c6bb9c7961f7015a615d0406","gzip_base64":""}]}\n'
import base64,gzip,hashlib,json,os
from pathlib import Path
packet=json.loads(PACKET_TEXT)
allowed=({'801_http.py','801_prepare.py','801_stage1.py'} if packet['stage']=='s1' else {'801_http.py','801_stage2.py'} if packet['stage']=='s2' else set())
target=Path(os.environ['T44_DIAG801_INSTALL_DIR'])
if not allowed or not target.is_absolute(): raise ValueError('New absolute target and known stage required')
files=[]
for item in packet['files']:
 if item['name'] not in allowed: raise ValueError('Unknown source')
 raw=gzip.decompress(base64.b64decode(item['gzip_base64'],validate=True))
 if len(raw)!=item['bytes'] or hashlib.sha256(raw).hexdigest()!=item['sha256']: raise ValueError('Hash mismatch')
 files.append((item['name'],raw))
if len(files)!=len(allowed) or {name for name,_ in files}!=allowed: raise ValueError('Exact files required')
target.mkdir(mode=0o700)
for name,raw in files:
 fd=os.open(target/name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o444)
 try:
  while raw:
   count=os.write(fd,raw)
   if count<=0: raise OSError('No progress')
   raw=raw[count:]
 finally: os.close(fd)
target.chmod(0o555)
print(json.dumps({'source':packet['source'],'stage':packet['stage'],'installed_public_sources_only':len(files)}))
